(() => {
const baseHome=homePage, baseRecords=recordsPage, baseSettings=settingsPage, baseRender=render, basePhoto=photoStep, baseHandle=handlePhoto;
const sources=[
['健康饮食、合理膳食核心信息','国家卫健委','2025-05','https://www.nhc.gov.cn/sps/c100088/202505/6b7a718abd4848e8a3e98fc561a8858b.shtml','🥬'],
['食品营养标签通则问答','国家卫健委','2025-09','https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml','🏷️'],
['健康素养基本知识与技能释义','国家卫健委','2024-04','https://www.nhc.gov.cn/xcs/c100123/202404/c30d31cb877749ce94ce23d2c55ad973/files/1733220375762_77083.pdf','📖'],
['不同人群的食养指南','国家卫健委','2026-04','https://www.nhc.gov.cn/sps/c100087/202604/a69d2fce21e040dc96cbc40b923a06d3.shtml','🍱'],
['谷物与蔬菜的食物营养','中国疾控中心','2026-10','https://www.chinacdc.cn/jkkp/yyjk/swyy/202610/t20261019_1842366.html','🌾'],
['节日饮食与营养标签','中国疾控中心','2026-10','https://www.chinacdc.cn/jkkp/yyjk/jbyy/202610/t20261010_1842151.html','🍽️'],
['一碗粥与一碗米饭的能量比较','北京市卫健委','2024-11','https://wjw.beijing.gov.cn/bmfw_20143/jkzs/jksh/202411/t20241121_3947159.html','🍚'],
['成人肥胖食养指南等资料','国家卫健委','2024-02','https://www.nhc.gov.cn/wjw/c100378/202402/afd5dda4bd6745fda10aad8d43a16369.shtml','📚'],
['营养指导员服务技术指南解读','国家卫健委','2026-06','https://www.nhc.gov.cn/sps/c100087/202606/337eaf4f774b4c6b94c30ee3423df5.shtml','🔎']];
function dateOf(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function weekStart(d){let x=new Date(d+'T12:00:00');x.setDate(x.getDate()-(x.getDay()+6)%7);return dateOf(x)}
function reportCard(){return `<section class="card report-card"><div><div class="eyebrow">DAILY & WEEKLY BRIEFING</div><h2>饮食日报与周报</h2><p>普通版在次日 00:00 后查看上一天的日报；每周一查看上周周报。根据已保存的记录生成，报告入口始终显示在首页。</p><div class="report-actions">${btn('查看日报','v3-report','btn primary','data-kind="day"')}${btn('查看周报','v3-report','btn','data-kind="week"')}${btn('预览报告样例','v3-report','textbtn','data-kind="sample"')}</div></div><span style="font-size:38px">📊</span></section>`}
function openReport(kind){let now=today(),prev=new Date(now+'T12:00:00');prev.setDate(prev.getDate()-1);let yesterday=dateOf(prev),weekEnd=weekStart(now),prior=new Date(weekEnd+'T12:00:00');prior.setDate(prior.getDate()-7);let start=dateOf(prior),sample=kind==='sample';let ms=sample?data().ms:state.meals.filter(m=>kind==='day'?m.date===yesterday:m.date>=start&&m.date<weekEnd);let ws=sample?data().ws:state.water.filter(w=>kind==='day'?w.date===yesterday:w.date>=start&&w.date<weekEnd);let cal=ms.reduce((v,m)=>v+(Number(m.cal)||0),0),water=ws.reduce((v,w)=>v+w.amount,0),rated=ms.filter(m=>m.after&&m.score);modal(sample?'饮食报告样例':kind==='week'?'上周饮食周报':'昨日饮食日报',`<div class="report-stats"><div><b>${ms.length}</b>餐次</div><div><b>${cal}</b>已记录 kcal</div><div><b>${water}</b>饮水 ml</div><div><b>${rated.length?Math.round(rated.reduce((v,m)=>v+m.score,0)/rated.length*10)/10:'—'}</b>心情 /10</div></div>${ms.length?ms.map(m=>`<div class="report-row"><span>${esc(m.type)} · ${esc(m.food)}</span><b>${m.cal??'未填'} kcal</b></div>`).join(''):'<div class="empty">该时段没有记录。完成记录后，次日或下周一即可查看已结束时段的报告。</div>'}<p class="help">${sample?'用首页演示数据生成的样例。':'只统计本浏览器已保存的记录。'}估算值与填写内容可能存在误差，不能据此判断营养是否充足。</p>`,btn('完成','close','btn primary'))}
homePage=function(){return baseHome().replace('class="btn primary" data-action="entry" ','class="btn primary" data-action="entry" data-mode="photo" ').replace('<div class="dashboard">',reportCard()+'<div class="dashboard">').replace('</div></section><div class="quick-grid">',`<div class="food-reference"><b>把 100 kcal 换成食物参照</b><span>🍚 约 86 克熟米饭 ≈ 100 kcal</span><small>北京市卫健委资料：每 100 克米饭约 116 kcal。品种、烹饪和份量均会影响实际热量。<a href="${sources[6][3]}" target="_blank" rel="noopener noreferrer">查看原文 ↗</a></small></div></div></section><div class="quick-grid">`)};
recordsPage=function(){return reportCard()+baseRecords()};
knowledgePage=function(){let item=sources[Math.floor(Date.now()/86400000)%sources.length];return `${head('健康知识，阅读国内来源。','精选中国大陆公共卫生机构资料，点开即可核对原文。','HEALTH LIBRARY')}<div class="knowledgehero"><div><div class="eyebrow">今日推荐 · 每天轮换</div><h2>${item[0]}</h2><p>${item[1]} · ${item[2]} 发布。推荐每日轮换，原文更新以来源网站为准。</p><a class="btn primary" href="${item[3]}" target="_blank" rel="noopener noreferrer" style="margin-top:15px">阅读原文 ↗</a></div><div class="art">${item[4]}</div></div><div class="articles">${sources.map(s=>`<a class="article" href="${s[3]}" target="_blank" rel="noopener noreferrer" style="color:inherit;text-decoration:none"><div class="article-art" style="--art-bg:#e8f3ec">${s[4]}</div><div class="article-body"><span class="tag gray">国内原文</span><h3>${s[0]}</h3><p>点击阅读原文 ↗</p><div class="article-meta"><span>${s[1]}</span><span>${s[2]}</span></div></div></a>`).join('')}</div>`};
settingsPage=function(){return baseSettings().replace('2.1 产品方案草案','3.0 全部免费方案').replace('为更长期的了解，升级 Pro','食刻 AI · 全部功能免费').replace('更多分析次数、长期心情趋势与每周回顾。','饮食记录、拍照识别入口、AI 助手、报告与健康知识全部免费使用。').replace('查看 Pro 权益 →','查看免费功能 →').replace(/FREE · 演示/g,'免费 · 完整功能')};
proModal=function(){modal('食刻 AI · 全部免费',`<div class="pro-banner"><h2>完整功能免费使用</h2><p>饮食记录、拍照入口、AI 助手、日报周报和健康知识均可使用。</p></div><p class="help">当前版本不设置 Pro 会员、付费额度或支付流程。AI 助手已接入服务端，连接失败时使用本地摘要；照片可通过服务端 AI 分析，失败时可手动填写。</p>`,btn('知道了','close','btn primary'))};
render=function(){baseRender();document.querySelectorAll('.previewbadge').forEach(el=>el.textContent='3.0 交互预览');document.querySelectorAll('.sidepro').forEach(el=>{el.innerHTML='<strong>食刻 AI · 全部免费</strong><p>完整记录、分析和健康知识功能，免费使用。</p>'});document.querySelectorAll('[data-action="pro"]').forEach(el=>el.textContent='查看免费功能 →')};
document.addEventListener('click',e=>{let b=e.target.closest('[data-action="v3-report"],[data-action="v3-payment"],[data-action="v3-method"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.action==='v3-report')openReport(b.dataset.kind);if(b.dataset.action==='v3-payment')modal('选择支付方式',`<div class="price-banner"><b>食刻 Pro · ¥9.9 / 月</b><p>支付界面预览 · 当前不会创建订单或扣款</p></div><div class="payment-methods">${['微信支付','支付宝','银行卡'].map((n,i)=>btn(['🟢','🔵','💳'][i]+'　'+n,'v3-method','btn wide',`data-method="${n}"`)).join('')}</div><p class="help">上线前需要商户账号、支付回调、订阅及退款规则。</p>`,btn('返回方案','pro','btn'));if(b.dataset.action==='v3-method'){document.querySelectorAll('.payment-methods button').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('.price-banner p').textContent=`已选择${b.dataset.method} · 当前是交互预览，不会扣款`}},true);
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="http"]');if(a){a.target='_self';a.removeAttribute('rel')}},true);
render();
})();
